1|// Deterministic music track prompts. Every track shares one base (same
2|// chamber orchestra, same folk-like leitmotif) so the 15 tracks sound
3|// like one soundtrack; mood, dynamics, and tempo vary per cluster.
4|import type { EmotionId } from "./types";
5|
6|export const SOUNDTRACK_BASE =
7|  "Storybook fantasy film score for chamber orchestra: strings, flute, clarinet, oboe, French horn, harp, celesta, timpani and light percussion, with a recurring simple folk-like leitmotif in a major key, instrumental, no vocals, seamless loop.";
8|
9|const MOOD_WORDS: Record<EmotionId, string> = {
10|  calma: "calm and gentle",
11|  alegria: "bright and joyful",
12|  tristeza: "tender and sorrowful",
13|  suspenso: "tense and expectant",
14|  misterio: "mysterious and veiled",
15|  aventura: "bold and roaming",
16|  combate: "driving and fierce",
17|  asombro: "wonder filled and luminous",
18|};
19|
20|// Picture book scoring stays in a playable acoustic range.
21|export function bpmRange(tempo: number): [number, number] {
22|  const center = Math.round(60 + tempo * 100);
23|  return [center - 10, center + 10];
24|}
25|
26|function dynamics(intensity: number): string {
27|  if (intensity < 0.33) return "soft dynamics";
28|  if (intensity < 0.67) return "moderate dynamics";
29|  return "strong dynamics";
30|}
31|
32|export function buildTrackPrompt(input: {
33|  top: { id: EmotionId; weight: number }[];
34|  intensity: number;
35|  tempo: number;
36|}): string {
37|  const moods = input.top
38|    .slice(0, 2)
39|    .map((t) => MOOD_WORDS[t.id])
40|    .join(", ");
41|  const [lo, hi] = bpmRange(input.tempo);
42|  const prompt = `${SOUNDTRACK_BASE} Mood ${moods}, ${dynamics(input.intensity)}, ${lo}-${hi} BPM.`;
43|  if (prompt.length <= 400) return prompt;
44|  return `${SOUNDTRACK_BASE} Mood ${MOOD_WORDS[input.top[0]?.id ?? "calma"]}, ${dynamics(input.intensity)}, ${lo}-${hi} BPM.`;
45|}

