1|// Emotion decision logic: when Jev needs a Muse override, and how the
2|// final 8-emotion vector is assembled. Pure, no network.
3|import { EMOTIONS, LOW_CONFIDENCE } from "./types";
4|import type { EmotionId, JevEmotionId, SceneEmotion, Vector8 } from "./types";
5|
6|export { LOW_CONFIDENCE };
7|
8|export function needsOverride(input: {
9|  choice: JevEmotionId;
10|  confidence: number;
11|  probabilities: Partial<Record<JevEmotionId, number>>;
12|}): boolean {
13|  if (input.choice === "unknown") return true;
14|  if (input.confidence < LOW_CONFIDENCE) return true;
15|  let maxId: JevEmotionId = input.choice;
16|  let maxValue = -Infinity;
17|  for (const [id, value] of Object.entries(input.probabilities)) {
18|    if (typeof value === "number" && value > maxValue) {
19|      maxValue = value;
20|      maxId = id as JevEmotionId;
21|    }
22|  }
23|  return maxId === "unknown";
24|}
25|
26|// Clamps negatives to 0, fills missing ids with 0, scales to sum 1.
27|// Returns null when the vector is all zero (a failure, never a guess).
28|export function renormalize8(vector: Partial<Record<EmotionId, number>>): Vector8 | null {
29|  const clamped = {} as Vector8;
30|  let sum = 0;
31|  for (const id of EMOTIONS) {
32|    const value = Math.max(0, vector[id] ?? 0);
33|    clamped[id] = value;
34|    sum += value;
35|  }
36|  if (sum <= 0) return null;
37|  for (const id of EMOTIONS) clamped[id] /= sum;
38|  return clamped;
39|}
40|
41|// Direct Jev path: drop `unknown` and renormalize. Intensity and tempo
42|// always come from Jev, even after an override.
43|export function jevFinal(input: {
44|  probabilities: Partial<Record<JevEmotionId, number>>;
45|  intensity: number;
46|  tempo: number;
47|}): SceneEmotion["final"] {
48|  const { unknown: _dropped, ...rest } = input.probabilities;
49|  const vector = renormalize8(rest);
50|  if (vector === null) return null;
51|  return { vector, intensity: input.intensity, tempo: input.tempo };
52|}

