1|// Gutenberg ingest: strip the license wrapper, drop front matter, split
2|// chapters into paragraphs with global ordinals.
3|import type { Book, Chapter, Paragraph } from "./types";
4|
5|const START_MARKER = "*** START OF THE PROJECT GUTENBERG EBOOK";
6|const END_MARKER = "*** END OF THE PROJECT GUTENBERG EBOOK";
7|
8|// Matches a real chapter heading line ("Chapter I") after trimming, so the
9|// indented Contents lines (" Chapter I. The Cyclone") never match.
10|export const CHAPTER_HEADING = /^Chapter ([IVXLC]+)$/;
11|
12|export function stripGutenberg(raw: string): string {
13|  const start = raw.indexOf(START_MARKER);
14|  const end = raw.indexOf(END_MARKER);
15|  if (start === -1 || end === -1 || end <= start) {
16|    throw new Error("Gutenberg START/END markers missing or out of order");
17|  }
18|  const startLine = raw.indexOf("\n", start);
19|  const endLine = raw.lastIndexOf("\n", end);
20|  return raw.slice(startLine + 1, endLine);
21|}
22|
23|export function splitParagraphs(text: string): string[] {
24|  return text
25|    .replace(/\r\n?/g, "\n")
26|    .split(/\n[ \t]*\n/)
27|    .map((block) => block.replace(/[ \t]*\n[ \t]*/g, " ").replace(/\s+/g, " ").trim())
28|    .filter((block) => block.length > 0);
29|}
30|
31|interface ChapterDraft {
32|  title: string;
33|  paragraphs: string[];
34|}
35|
36|// Splits stripped body text into chapters. Works line by line because
37|// the heading and its title sit on adjacent lines with no blank line
38|// between them. Drops everything before the first chapter heading
39|// (title page, Contents, Introduction) and any [Illustration...] line.
40|export function splitChapters(body: string): ChapterDraft[] {
41|  const chapters: ChapterDraft[] = [];
42|  let current: ChapterDraft | null = null;
43|  let titlePending = false;
44|  let buffer: string[] = [];
45|  const flush = (): string => {
46|    const para = buffer.join(" ").replace(/\s+/g, " ").trim();
47|    buffer = [];
48|    return para;
49|  };
50|  const pushPara = (para: string): void => {
51|    if (para.length === 0 || /^\[Illustration/.test(para)) return;
52|    if (current === null) return; // front matter before chapter one
53|    if (titlePending) {
54|      current.title = para;
55|      titlePending = false;
56|      return;
57|    }
58|    current.paragraphs.push(para);
59|  };
60|  for (const line of body.replace(/\r\n?/g, "\n").split("\n")) {
61|    const trimmed = line.trim();
62|    if (trimmed.length === 0) {
63|      pushPara(flush());
64|      continue;
65|    }
66|    if (CHAPTER_HEADING.exec(trimmed)) {
67|      pushPara(flush());
68|      current = { title: "", paragraphs: [] };
69|      chapters.push(current);
70|      titlePending = true;
71|      continue;
72|    }
73|    buffer.push(trimmed);
74|  }
75|  pushPara(flush());
76|  return chapters.filter((chapter) => chapter.paragraphs.length > 0);
77|}
78|
79|export function buildBook(input: {
80|  id: string;
81|  title: string;
82|  author: string;
83|  gutenberg: number;
84|  chapters: { title: string; paragraphs: string[] }[];
85|}): Omit<Book, "textVersion"> {
86|  const chapters: Chapter[] = [];
87|  const paragraphs: Paragraph[] = [];
88|  let n = 0;
89|  input.chapters.forEach((draft, index) => {
90|    const ch = index + 1;
91|    const start_n = n + 1;
92|    draft.paragraphs.forEach((text, k) => {
93|      n += 1;
94|      paragraphs.push({ id: `c${ch}p${k + 1}`, ch, n, text });
95|    });
96|    chapters.push({ ch, title: draft.title, start_n, end_n: n });
97|  });
98|  return {
99|    id: input.id,
100|    title: input.title,
101|    author: input.author,
102|    source: {
103|      gutenberg: input.gutenberg,
104|      url: `https://www.gutenberg.org/ebooks/${input.gutenberg}`,
105|    },
106|    chapters,
107|    paragraphs,
108|  };
109|}
110|
111|// Canonical hash input: one `id\ttext` line per paragraph.
112|export function canonicalLines(paragraphs: Pick<Paragraph, "id" | "text">[]): string {
113|  return paragraphs.map((p) => `${p.id}\t${p.text}`).join("\n");
114|}

