1|// Scene coverage validators. Problems are data, not throws, so the
2|// caller can paste them into the retry prompt and then fail loudly.
3|import type { Book, Chapter, Scene, SceneInput } from "./types";
4|
5|export interface CoverageProblem {
6|  code: "gap" | "overlap" | "bad-start" | "bad-end" | "order" | "cross-chapter" | "out-of-range";
7|  message: string;
8|}
9|
10|export function validateSceneCoverage(chapter: Chapter, scenes: SceneInput[]): CoverageProblem[] {
11|  const problems: CoverageProblem[] = [];
12|  if (scenes.length === 0) {
13|    problems.push({ code: "gap", message: `chapter ${chapter.ch} has no scenes` });
14|    return problems;
15|  }
16|  const first = scenes[0];
17|  if (first && first.start_n !== chapter.start_n) {
18|    problems.push({
19|      code: "bad-start",
20|      message: `first scene starts at ${first.start_n}, chapter starts at ${chapter.start_n}`,
21|    });
22|  }
23|  scenes.forEach((scene, i) => {
24|    if (scene.start_n < chapter.start_n || scene.end_n > chapter.end_n) {
25|      problems.push({
26|        code: "out-of-range",
27|        message: `scene ${i} [${scene.start_n}..${scene.end_n}] outside chapter [${chapter.start_n}..${chapter.end_n}]`,
28|      });
29|    }
30|    if (scene.start_n > scene.end_n) {
31|      problems.push({ code: "order", message: `scene ${i} starts after it ends` });
32|    }
33|    if (i === 0) return;
34|    const prev = scenes[i - 1];
35|    if (prev && scene.start_n === prev.end_n + 1) return;
36|    if (prev && scene.start_n <= prev.end_n) {
37|      problems.push({ code: "overlap", message: `scene ${i} starts at ${scene.start_n} inside previous scene ending at ${prev.end_n}` });
38|    } else if (prev) {
39|      problems.push({ code: "gap", message: `gap between scene ${i - 1} ending at ${prev.end_n} and scene ${i} starting at ${scene.start_n}` });
40|    }
41|  });
42|  const last = scenes[scenes.length - 1];
43|  if (last && last.end_n !== chapter.end_n) {
44|    problems.push({
45|      code: "bad-end",
46|      message: `last scene ends at ${last.end_n}, chapter ends at ${chapter.end_n}`,
47|    });
48|  }
49|  return problems;
50|}
51|
52|// Whole book check: no scene crosses a chapter, and the union covers
53|// every paragraph exactly once.
54|export function validateBookCoverage(
55|  book: Pick<Book, "chapters" | "paragraphs">,
56|  scenes: Scene[],
57|): CoverageProblem[] {
58|  const problems: CoverageProblem[] = [];
59|  const byCh = new Map(book.chapters.map((c) => [c.ch, c]));
60|  const total = book.paragraphs.length;
61|  const seen = new Array<boolean>(total + 1).fill(false);
62|  for (const scene of scenes) {
63|    const chapter = byCh.get(scene.ch);
64|    if (!chapter) {
65|      problems.push({ code: "cross-chapter", message: `scene ${scene.id} names unknown chapter ${scene.ch}` });
66|      continue;
67|    }
68|    if (scene.start_n < chapter.start_n || scene.end_n > chapter.end_n) {
69|      problems.push({ code: "cross-chapter", message: `scene ${scene.id} crosses chapter ${scene.ch} bounds` });
70|    }
71|    for (let n = scene.start_n; n <= scene.end_n; n++) {
72|      if (n < 1 || n > total) {
73|        problems.push({ code: "out-of-range", message: `scene ${scene.id} covers ordinal ${n} outside 1..${total}` });
74|        continue;
75|      }
76|      if (seen[n]) {
77|        problems.push({ code: "overlap", message: `ordinal ${n} covered twice` });
78|      }
79|      seen[n] = true;
80|    }
81|  }
82|  for (let n = 1; n <= total; n++) {
83|    if (!seen[n]) problems.push({ code: "gap", message: `ordinal ${n} covered by no scene` });
84|  }
85|  return problems;
86|}

Read text file `core/cluster.ts`.
1|// Deterministic k-means over scene features. Same input gives
2|// byte-identical output: seeded init, fixed restarts, sorted naming.
3|import { EMOTIONS, FEATURE_WEIGHTS } from "./types";
4|import type { EmotionId, Vector8 } from "./types";
5|
6|export interface WeightedPoint {
7|  sceneId: string;
8|  features: number[]; // 8 vector values, then intensity, then tempo
9|}
10|
11|export interface KmeansCluster {
12|  points: WeightedPoint[];
13|  centroid: number[];
14|  inertia: number;
15|}
16|
17|export function mulberry32(seed: number): () => number {
18|  let state = seed >>> 0;
19|  return () => {
20|    state = (state + 0x6d2b79f5) >>> 0;
21|    let t = state;
22|    t = Math.imul(t ^ (t >>> 15), t | 1);
23|    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
24|    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
25|  };
26|}
27|
28|// Intensity and tempo each weigh half an emotion slot, so mood still
29|// decides the grouping while energy breaks ties.
30|export function buildFeatures(input: { vector: Vector8; intensity: number; tempo: number }): number[] {
31|  const features = EMOTIONS.map((id: EmotionId) => input.vector[id]);
32|  features.push(input.intensity * FEATURE_WEIGHTS.intensity);
33|  features.push(input.tempo * FEATURE_WEIGHTS.tempo);
34|  return features;
35|}
36|
37|function distance(a: number[], b: number[]): number {
38|  let sum = 0;
39|  for (let i = 0; i < a.length; i++) {
40|    const diff = (a[i] ?? 0) - (b[i] ?? 0);
41|    sum += diff * diff;
42|  }
43|  return sum;
44|}
45|
46|function mean(points: WeightedPoint[]): number[] {
47|  const dims = points[0]?.features.length ?? 0;
48|  const centroid = new Array<number>(dims).fill(0);
49|  for (const point of points) {
50|    for (let d = 0; d < dims; d++) centroid[d] = (centroid[d] ?? 0) + (point.features[d] ?? 0);
51|  }
52|  return centroid.map((value) => value / points.length);
53|}
54|
55|function kmeansPlusPlus(points: WeightedPoint[], k: number, rand: () => number): number[][] {
56|  const centroids: number[][] = [];
57|  centroids.push([...(points[Math.floor(rand() * points.length)]?.features ?? [])]);
58|  while (centroids.length < k) {
59|    const weights = points.map((p) => Math.min(...centroids.map((c) => distance(p.features, c))));
60|    const total = weights.reduce((a, b) => a + b, 0);
61|    if (total <= 0) {
62|      centroids.push([...(points[centroids.length % points.length]?.features ?? [])]);
63|      continue;
64|    }
65|    let pick = rand() * total;
66|    let chosen = points[points.length - 1]?.features ?? [];
67|    for (let i = 0; i < points.length; i++) {
68|      pick -= weights[i] ?? 0;
69|      if (pick <= 0) {
70|        chosen = points[i]?.features ?? [];
71|        break;
72|      }
73|    }
74|    centroids.push([...chosen]);
75|  }
76|  return centroids;
77|}
78|
79|export function kmeans(
80|  points: WeightedPoint[],
81|  k: number,
82|  opts?: { seed?: number; restarts?: number; maxIter?: number },
83|): KmeansCluster[] {
84|  const seed = opts?.seed ?? 42;
85|  const restarts = opts?.restarts ?? 20;
86|  const maxIter = opts?.maxIter ?? 100;
87|  if (points.length === 0 || k <= 0) return [];
88|  const clampedK = Math.min(k, points.length);
89|  let best: KmeansCluster[] | null = null;
90|  for (let r = 0; r < restarts; r++) {
91|    const rand = mulberry32(seed + r);
92|    let centroids = kmeansPlusPlus(points, clampedK, rand);
93|    let assign = new Array<number>(points.length).fill(0);
94|    for (let iter = 0; iter < maxIter; iter++) {
95|      const next = points.map((p) => {
96|        let bi = 0;
97|        let bd = Infinity;
98|        centroids.forEach((c, i) => {
99|          const d = distance(p.features, c);
100|          if (d < bd) {
101|            bd = d;
102|            bi = i;
103|          }
104|        });
105|        return bi;
106|      });
107|      // An empty cluster restarts at the point farthest from its centroid.
108|      const counts = new Array<number>(clampedK).fill(0);
109|      for (const a of next) counts[a] = (counts[a] ?? 0) + 1;
110|      for (let c = 0; c < clampedK; c++) {
111|        if ((counts[c] ?? 0) === 0) {
112|          let far = 0;
113|          let farD = -1;
114|          points.forEach((p, i) => {
115|            const d = distance(p.features, centroids[next[i] ?? 0] ?? []);
116|            if (d > farD) {
117|              farD = d;
118|              far = i;
119|            }
120|          });
121|          centroids[c] = [...(points[far]?.features ?? [])];
122|          next[far] = c;
123|        }
124|      }
125|      const moved = next.some((a, i) => a !== assign[i]);
126|      assign = next;
127|      const groups = centroids.map((_, c) => points.filter((_, i) => assign[i] === c));
128|      centroids = groups.map((g, c) => (g.length > 0 ? mean(g) : (centroids[c] ?? [])));
129|      if (!moved) break;
130|    }
131|    const candidate: KmeansCluster[] = centroids.map((centroid, c) => {
132|      const members = points.filter((_, i) => assign[i] === c);
133|      const inertia = members.reduce((sum, p) => sum + distance(p.features, centroid), 0);
134|      return { points: members, centroid, inertia };
135|    });
136|    const total = candidate.reduce((sum, c) => sum + c.inertia, 0);
137|    if (best === null || total < best.reduce((sum, c) => sum + c.inertia, 0)) best = candidate;
138|  }
139|  return best ?? [];
140|}
141|
142|// Dominant emotion index decides cluster order, then intensity.
143|export function dominantIndex(centroid: number[]): number {
144|  let best = 0;
145|  let bestValue = -Infinity;
146|  for (let i = 0; i < EMOTIONS.length; i++) {
147|    const value = centroid[i] ?? 0;
148|    if (value > bestValue) {
149|      bestValue = value;
150|      best = i;
151|    }
152|  }
153|  return best;
154|}

