1|// Gutenberg ingest: strip the license wrapper, drop front matter, split
2|// chapters into paragraphs with global ordinals.
3|import type { Book, Chapter, Paragraph } from "./types";
4|
5|const START_MARKER = "*** START OF THE PROJECT GUTENBERG EBOOK";
6|const END_MARKER = "*** END OF THE PROJECT GUTENBERG EBOOK";
7|
8|// Matches a real chapter heading line ("Chapter I") after trimming, so the
9|// indented Contents lines (" Chapter I. The Cyclone") never match.
10|export const CHAPTER_HEADING = /^Chapter ([IVXLC]+)$/;
11|
12|export function stripGutenberg(raw: string): string {
13|  const start = raw.indexOf(START_MARKER);
14|  const end = raw.indexOf(END_MARKER);
15|  if (start === -1 || end === -1 || end <= start) {
16|    throw new Error("Gutenberg START/END markers missing or out of order");
17|  }
18|  const startLine = raw.indexOf("\n", start);
19|  const endLine = raw.lastIndexOf("\n", end);
20|  return raw.slice(startLine + 1, endLine);
21|}
22|
23|export function splitParagraphs(text: string): string[] {
24|  return text
25|    .replace(/\r\n?/g, "\n")
26|    .split(/\n[ \t]*\n/)
27|    .map((block) => block.replace(/[ \t]*\n[ \t]*/g, " ").replace(/\s+/g, " ").trim())
28|    .filter((block) => block.length > 0);
29|}
30|
31|interface ChapterDraft {
32|  title: string;
33|  paragraphs: string[];
34|}
