36|// Splits stripped body text into chapters. Works line by line because
37|// the heading and its title sit on adjacent lines with no blank line
38|// between them. Drops everything before the first chapter heading
39|// (title page, Contents, Introduction) and any [Illustration...] line.
40|export function splitChapters(body: string): ChapterDraft[] {
41|  const chapters: ChapterDraft[] = [];
42|  let current: ChapterDraft | null = null;
43|  let titlePending = false;
44|  let buffer: string[] = [];
45|  const flush = (): string => {
46|    const para = buffer.join(" ").replace(/\s+/g, " ").trim();
47|    buffer = [];
48|    return para;
49|  };
50|  const pushPara = (para: string): void => {
51|    if (para.length === 0 || /^\[Illustration/.test(para)) return;
52|    if (current === null) return; // front matter before chapter one
53|    if (titlePending) {
54|      current.title = para;
55|      titlePending = false;
56|      return;
57|    }
58|    current.paragraphs.push(para);
59|  };
60|  for (const line of body.replace(/\r\n?/g, "\n").split("\n")) {
61|    const trimmed = line.trim();
62|    if (trimmed.length === 0) {
63|      pushPara(flush());
64|      continue;
65|    }
66|    if (CHAPTER_HEADING.exec(trimmed)) {
67|      pushPara(flush());
68|      current = { title: "", paragraphs: [] };
69|      chapters.push(current);
70|      titlePending = true;
71|      continue;
72|    }
73|    buffer.push(trimmed);
74|  }
75|  pushPara(flush());
76|  return chapters.filter((chapter) => chapter.paragraphs.length > 0);
77|}
