86|  const chapters: Chapter[] = [];
87|  const paragraphs: Paragraph[] = [];
88|  let n = 0;
89|  input.chapters.forEach((draft, index) => {
90|    const ch = index + 1;
91|    const start_n = n + 1;
92|    draft.paragraphs.forEach((text, k) => {
93|      n += 1;
94|      paragraphs.push({ id: `c${ch}p${k + 1}`, ch, n, text });
95|    });
96|    chapters.push({ ch, title: draft.title, start_n, end_n: n });
97|  });
98|  return {
99|    id: input.id,
100|    title: input.title,
101|    author: input.author,
102|    source: {
103|      gutenberg: input.gutenberg,
104|      url: `https://www.gutenberg.org/ebooks/${input.gutenberg}`,
105|    },
106|    chapters,
