39|async function classifyScene(
40|  scene: Scene,
41|  text: string,
42|  bookTitle: string,
43|  chapterTitle: string,
44|  deps: { jev: JevClient; meta: MetaClient },
45|  metaUsage: ClassifyMetaUsage,
