50|  } catch (error) {
51|    return { jev: null, muse_override: null, final: null, error: `jev failed: ${(error as Error).message}` };
52|  }
53|  if (!needsOverride({ choice: jev.choice, confidence: jev.confidence, probabilities: jev.vector })) {
54|    const final = jevFinal({ probabilities: jev.vector, intensity: jev.intensity, tempo: jev.tempo });
55|    return { jev, muse_override: null, final, error: final === null ? "jev vector renormalizes to zero" : null };
56|  }
