68|    metaUsage.promptTokens += result.promptTokens;
69|    metaUsage.cachedTokens += result.cachedTokens;
70|    metaUsage.completionTokens += result.completionTokens;
71|    const parsed = result.data as { vector?: Partial<Record<EmotionId, number>>; reason?: unknown };
72|    const vector = renormalize8(parsed.vector ?? {});
73|    if (vector === null) {
