83|export async function runClassify(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
84|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
85|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
