87|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
88|  };
89|  const outPath = join(ctx.dir, "analysis.json");
90|  if (!ctx.force) {
91|    const fresh = readIfFresh<{ textVersion: string; scenes: AnalyzedScene[] }>(outPath, book.textVersion);
92|    if (fresh) return fresh.scenes;
93|  }
94|  const metaUsage: ClassifyMetaUsage = { model: deps.meta.model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 };
95|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
96|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
97|  let jevInputTokens = 0;
98|  let jevOutputTokens = 0;
99|  let jevRequests = 0;
100|  const scenes = await runPool(scenesFile.scenes, 4, async (scene) => {
101|    const texts: string[] = [];
