1|// Jev emotion client. The state and questions builder lives here, not
2|// in core, so core stays free of API shapes.
3|import { EMOTIONS } from "../core/types";
4|import type { EmotionId, JevEmotionId, JevResult, Vector9 } from "../core/types";
5|import { fetchWithRetry } from "./http";
6|
7|export type { JevResult };
8|
9|export interface JevClient {
10|  model: string;
11|  classify(input: { book: string; chapter: string; sceneTitle: string; scene: string }): Promise<JevResult>;
12|}
13|
14|const JEV_URL = "https://api.typesafe.ai/v1/systemone";
15|const SCORE_LEVELS = 5;
16|
17|const EMOTION_DESCRIPTIONS: Record<EmotionId | "unknown", string> = {
18|  calma: "Calm, peaceful, safe at rest",
19|  alegria: "Joyful, warm, celebratory",
20|  tristeza: "Sad, mournful, grieving",
21|  suspenso: "Tense, expectant, danger near",
22|  misterio: "Mysterious, veiled, uncanny",
23|  aventura: "Adventurous, bold, on the road",
24|  combate: "Fierce, confrontational, fighting",
25|  asombro: "Awe struck, wonder filled",
26|  unknown: "None of the feelings above fits",
27|};
28|
29|function buildQuestions(): Record<string, unknown> {
30|  const criteria: Record<string, string> = {};
31|  for (const id of [...EMOTIONS, "unknown"] as (EmotionId | "unknown")[]) criteria[id] = EMOTION_DESCRIPTIONS[id];
32|  return {
33|    emotion: {
34|      type: "choice",
35|      instructions: "Which feeling should the soundtrack carry for `scene`?",
36|      criteria,
37|    },
38|    intensity: {
39|      type: "score",
40|      instructions: "How strong is the emotional and dramatic intensity of `scene`?",
41|      criteria: ["very low", "low", "medium", "high", "very high"],
42|    },
43|    tempo: {
44|      type: "score",
45|      instructions: "How fast and urgent is the pace and energy of the action in `scene`?",
46|      criteria: ["very slow and still", "slow", "moderate", "fast", "very fast and urgent"],
47|    },
48|  };
49|}
50|
51|// Scene openings and endings carry the mood shift, so keep both ends.
52|export function capSceneText(text: string, limit = 12000): string {
53|  if (text.length <= limit) return text;
54|  const half = Math.floor(limit / 2);
55|  return `${text.slice(0, half)}\n[...]\n${text.slice(text.length - half)}`;
56|}
57|
58|function normalizeScore(score: number): number {
59|  return Math.min(1, Math.max(0, score / (SCORE_LEVELS - 1)));
60|}
61|
62|interface JevAnswer {
63|  choice?: unknown;
64|  confidence?: unknown;
65|  probabilities?: unknown;
66|  score?: unknown;
67|}
68|
69|function parseJevResponse(payload: unknown, model: string): Omit<JevResult, "inputTokens" | "outputTokens"> & { inputTokens: number; outputTokens: number } {
70|  const root = payload as {
71|    answers?: Record<string, JevAnswer>;
72|    usage?: { input_tokens?: number; output_tokens?: number };
73|  };
74|  const emotion = root.answers?.emotion ?? {};
75|  const intensity = root.answers?.intensity ?? {};
76|  const tempo = root.answers?.tempo ?? {};
77|  const vector = {} as Vector9;
78|  const probs = (emotion.probabilities ?? {}) as Record<string, unknown>;
79|  for (const id of [...EMOTIONS, "unknown"] as JevEmotionId[]) {
80|    const value = probs[id];
81|    vector[id] = typeof value === "number" && Number.isFinite(value) ? Math.max(0, value) : 0;
82|  }
83|  return {
84|    vector,
85|    choice: typeof emotion.choice === "string" ? (emotion.choice as JevEmotionId) : "unknown",
86|    confidence: typeof emotion.confidence === "number" ? emotion.confidence : 0,
87|    intensity: normalizeScore(typeof intensity.score === "number" ? intensity.score : 0),
88|    intensityConfidence: typeof intensity.confidence === "number" ? intensity.confidence : 0,
89|    tempo: normalizeScore(typeof tempo.score === "number" ? tempo.score : 0),
90|    tempoConfidence: typeof tempo.confidence === "number" ? tempo.confidence : 0,
91|    model,
92|    inputTokens: root.usage?.input_tokens ?? 0,
93|    outputTokens: root.usage?.output_tokens ?? 0,
94|  };
95|}
96|
97|export function createJevClient(input: { fetchFn?: typeof fetch; apiKey: string; model: string }): JevClient {
98|  const fetchFn = input.fetchFn ?? fetch;
99|  return {
100|    model: input.model,
101|    classify: async ({ book, chapter, sceneTitle, scene }) => {
102|      const body = JSON.stringify({
103|        model: input.model,
104|        state: { book, chapter, scene_title: sceneTitle, scene: capSceneText(scene) },
105|        questions: buildQuestions(),
106|      });
107|      const response = await fetchWithRetry(
108|        fetchFn,
109|        JEV_URL,
110|        {
111|          method: "POST",
112|          headers: { Authorization: `Bearer ${input.apiKey}`, "Content-Type": "application/json" },
113|          body,
114|        },
115|        { attempts: 3 },
116|      );
117|      return parseJevResponse(await response.json(), input.model);
118|    },
119|  };
