1|// Step 4: cluster classified scenes into about 15 track prompts.
2|// No network in this step and no audio code anywhere.
3|import { readFileSync, writeFileSync } from "node:fs";
4|import { join } from "node:path";
5|import { buildFeatures, dominantIndex, kmeans } from "../core/cluster";
6|import type { WeightedPoint } from "../core/cluster";
7|import { bpmRange, buildTrackPrompt } from "../core/music-prompt";
8|import { EMOTIONS, FEATURE_WEIGHTS } from "../core/types";
9|import type { AnalyzedScene, Book, EmotionId } from "../core/types";
10|import { readIfFresh } from "./cache";
11|import type { StepCtx } from "./ingest";
12|
13|const SEED = 42;
14|
15|export async function runCluster(ctx: StepCtx): Promise<void> {
16|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
17|  const analysis = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
18|    scenes: AnalyzedScene[];
19|  };
20|  const outPath = join(ctx.dir, "music-clusters.json");
21|  if (!ctx.force && readIfFresh(outPath, book.textVersion)) return;
22|  const classified = analysis.scenes.filter((s): s is AnalyzedScene & { final: NonNullable<AnalyzedScene["final"]> } => s.final !== null);
23|  const unclustered = analysis.scenes.filter((s) => s.final === null).map((s) => s.id);
24|  const points: WeightedPoint[] = classified.map((s) => ({
25|    sceneId: s.id,
26|    features: buildFeatures({ vector: s.final.vector, intensity: s.final.intensity, tempo: s.final.tempo }),
27|  }));
28|  const k = Math.min(15, points.length);
29|  const clusters = kmeans(points, k, { seed: SEED, restarts: 20, maxIter: 100 })
30|    .map((cluster) => {
31|      const intensity = Math.min(1, Math.max(0, (cluster.centroid[8] ?? 0) / FEATURE_WEIGHTS.intensity));
32|      const tempo = Math.min(1, Math.max(0, (cluster.centroid[9] ?? 0) / FEATURE_WEIGHTS.tempo));
33|      return { cluster, intensity, tempo, dominant: dominantIndex(cluster.centroid) };
34|    })
35|    .sort((a, b) => a.dominant - b.dominant || a.intensity - b.intensity)
36|    .map(({ cluster, intensity, tempo }, index) => {
37|      const vector = Object.fromEntries(EMOTIONS.map((id, i) => [id, cluster.centroid[i] ?? 0]));
38|      const top = (Object.entries(vector) as [EmotionId, number][]).sort((a, b) => b[1] - a[1]).slice(0, 2);
39|      const scenes = cluster.points
40|        .map((p) => classified.find((s) => s.id === p.sceneId))
41|        .filter((s) => s !== undefined)
42|        .sort((a, b) => a.start_n - b.start_n)
43|        .map((s) => s.id);
44|      return {
45|        id: `t${String(index + 1).padStart(2, "0")}`,
46|        size: cluster.points.length,
47|        centroid: { vector, intensity, tempo },
48|        dominant: top.map(([id]) => id),
49|        bpm: bpmRange(tempo),
50|        scenes,
51|        prompt: buildTrackPrompt({ top: top.map(([id, weight]) => ({ id, weight })), intensity, tempo }),
52|      };
53|    });
54|  writeFileSync(
55|    outPath,
56|    `${JSON.stringify({ bookId: book.id, textVersion: book.textVersion, k, seed: SEED, feature_weights: FEATURE_WEIGHTS, clusters, unclustered, provenance: { date: new Date().toISOString() } })}\n`,
57|  );
58|}

