1|// Step 2: one Meta call per chapter to split it into scenes. Invalid
2|// output retries once with the problems in the prompt, then fails the
3|// run with no silent repair.
4|import { readFileSync, writeFileSync } from "node:fs";
5|import { join } from "node:path";
6|import { validateSceneCoverage } from "../core/scenes";
7|import type { Book, Chapter, Scene, SceneInput } from "../core/types";
8|import { readIfFresh } from "./cache";
9|import type { StepCtx } from "./ingest";
10|import { runPool } from "./http";
11|import type { MetaClient } from "./meta";
12|import { metaCostUsd } from "./prices";
13|
14|const SCENE_SCHEMA = {
15|  type: "object",
16|  properties: {
17|    scenes: {
18|      type: "array",
19|      items: {
20|        type: "object",
21|        properties: {
22|          start_n: { type: "number" },
23|          end_n: { type: "number" },
24|          title: { type: "string" },
25|          summary: { type: "string" },
26|          characters: { type: "array", items: { type: "string" } },
27|        },
28|        required: ["start_n", "end_n", "title", "summary", "characters"],
29|        additionalProperties: false,
30|      },
31|    },
32|  },
33|  required: ["scenes"],
34|  additionalProperties: false,
35|};
36|
37|function chapterPrompt(chapter: Chapter, paragraphs: { n: number; text: string }[], problems?: string): string {
38|  const lines = paragraphs.map((p) => `[${p.n}] ${p.text}`).join("\n");
39|  const base =
40|    `Split chapter "${chapter.title}" into scenes in order. A scene is a stretch with one dominant mood, ` +
41|    `so the soundtrack can change inside the chapter at mood shifts (location change, danger starts or ends, a reveal). ` +
42|    `Usually 3 to 25 paragraphs per scene; a very short chapter may be one scene. ` +
43|    `Each scene needs start_n, end_n (global paragraph ordinals), title, summary, and characters. ` +
44|    `Cover every paragraph exactly once: first start_n is ${chapter.start_n}, last end_n is ${chapter.end_n}.\n\n${lines}`;
45|  return problems ? `${base}\n\nYour last answer had these coverage problems, fix them:\n${problems}` : base;
46|}
47|
48|function parseScenes(data: unknown): SceneInput[] {
49|  const scenes = (data as { scenes?: unknown })?.scenes;
50|  if (!Array.isArray(scenes)) throw new Error("Meta answer has no scenes array");
51|  return scenes.map((s) => {
52|    const scene = s as Record<string, unknown>;
53|    return {
54|      start_n: Number(scene.start_n),
55|      end_n: Number(scene.end_n),
56|      title: String(scene.title ?? ""),
57|      summary: String(scene.summary ?? ""),
58|      characters: Array.isArray(scene.characters) ? scene.characters.map(String) : [],
59|    };
60|  });
61|}
62|
63|export interface SegmentUsage {
64|  model: string;
65|  requests: number;
66|  promptTokens: number;
67|  cachedTokens: number;
68|  completionTokens: number;
69|  costUsd: number;
70|}
71|
72|export async function runSegment(ctx: StepCtx, deps: { meta: MetaClient }): Promise<Scene[]> {
73|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
74|  const outPath = join(ctx.dir, "scenes.json");
75|  if (!ctx.force) {
76|    const fresh = readIfFresh<{ textVersion: string; scenes: Scene[] }>(outPath, book.textVersion);
77|    if (fresh) return fresh.scenes;
78|  }
79|  const usage: SegmentUsage = {
80|    model: deps.meta.model,
81|    requests: 0,
82|    promptTokens: 0,
83|    cachedTokens: 0,
84|    completionTokens: 0,
85|    costUsd: 0,
86|  };
87|  const chapters = await runPool(book.chapters, 4, async (chapter) => {
88|    const paragraphs = book.paragraphs.filter((p) => p.ch === chapter.ch).map((p) => ({ n: p.n, text: p.text }));
89|    let problems: string | undefined;
90|    for (let attempt = 0; attempt < 2; attempt++) {
91|      const result = await deps.meta.completeJson({
92|        system: "You split book chapters into scenes for a music soundtrack. Answer with JSON only.",
93|        user: chapterPrompt(chapter, paragraphs, problems),
94|        schemaName: "chapter_scenes",
95|        schema: SCENE_SCHEMA,
96|      });
97|      usage.requests += 1;
98|      usage.promptTokens += result.promptTokens;
99|      usage.cachedTokens += result.cachedTokens;
100|      usage.completionTokens += result.completionTokens;
101|      const inputs = parseScenes(result.data);
102|      const found = validateSceneCoverage(chapter, inputs);
103|      if (found.length === 0) {
104|        return inputs.map((scene, k) => ({ ...scene, id: `c${chapter.ch}s${k + 1}`, ch: chapter.ch }) as Scene);
105|      }
106|      problems = found.map((p) => p.message).join("\n");
107|    }
108|    throw new Error(`chapter ${chapter.ch} scenes still invalid after retry: ${problems}`);
109|  });
110|  const scenes = chapters.flat();
111|  usage.costUsd = metaCostUsd({ prompt: usage.promptTokens, cached: usage.cachedTokens, completion: usage.completionTokens });
112|  writeFileSync(
113|    outPath,
114|    `${JSON.stringify({
115|      bookId: book.id,
116|      textVersion: book.textVersion,
117|      scenes,
118|      provenance: {
119|        date: new Date().toISOString(),
120|        meta: {
121|          model: usage.model,
122|          requests: usage.requests,
123|          prompt_tokens: usage.promptTokens,
124|          cached_tokens: usage.cachedTokens,
125|          completion_tokens: usage.completionTokens,
126|          cost_usd: usage.costUsd,
127|        },
128|      },
129|    })}\n`,
130|  );
131|  return scenes;
