87|    intensity: normalizeScore(typeof intensity.score === "number" ? intensity.score : 0),
88|    intensityConfidence: typeof intensity.confidence === "number" ? intensity.confidence : 0,
89|    tempo: normalizeScore(typeof tempo.score === "number" ? tempo.score : 0),
