3|import { fetchWithRetry, retryableError } from "./http";
4|
5|export interface MetaUsage {
6|  data: unknown;
7|  promptTokens: number;
8|  cachedTokens: number;
9|  completionTokens: number;
10|}
11|
12|export interface MetaClient {
13|  model: string;
14|  completeJson(input: {
15|    system: string;
16|    user: string;
17|    schemaName: string;
18|    schema: Record<string, unknown>;
19|  }): Promise<MetaUsage>;
20|}
21|
22|const META_URL = "https://api.meta.ai/v1/chat/completions";
23|
24|export function createMetaClient(input: { fetchFn?: typeof fetch; apiKey: string; model: string }): MetaClient {
25|  const fetchFn = input.fetchFn ?? fetch;
26|  return {
27|    model: input.model,
28|    completeJson: async ({ system, user, schemaName, schema }) => {
29|      const body = JSON.stringify({
30|        model: input.model,
31|        messages: [
32|          { role: "system", content: system },
33|          { role: "user", content: user },
34|        ],
35|        reasoning_effort: "low",
36|        max_tokens: 4000,
37|        response_format: { type: "json_schema", json_schema: { name: schemaName, strict: true, schema } },
38|      });
39|      // Small max_tokens can return empty content when reasoning eats the
40|      // budget, so empty or unparseable content retries like a 5xx.
41|      let lastError: unknown = null;
42|      for (let attempt = 1; attempt <= 3; attempt++) {
43|        const response = await fetchWithRetry(
44|          fetchFn,
45|          META_URL,
46|          {
47|            method: "POST",
48|            headers: { Authorization: `Bearer ${input.apiKey}`, "Content-Type": "application/json" },
49|            body,
50|          },
51|          { attempts: 3 },
52|        );
53|        const parsed = (await response.json()) as {
54|          choices?: { message?: { content?: string | null } }[];
55|          usage?: { prompt_tokens?: number; prompt_tokens_details?: { cached_tokens?: number }; completion_tokens?: number };
56|        };
57|        const content = parsed.choices?.[0]?.message?.content;
58|        if (typeof content === "string" && content.trim().length > 0) {
59|          try {
60|            return {
61|              data: JSON.parse(content) as unknown,
62|              promptTokens: parsed.usage?.prompt_tokens ?? 0,
63|              cachedTokens: parsed.usage?.prompt_tokens_details?.cached_tokens ?? 0,
64|              completionTokens: parsed.usage?.completion_tokens ?? 0,
65|            };
66|          } catch {
67|            lastError = retryableError("Meta returned unparseable JSON content");
68|          }
69|        } else {
70|          lastError = retryableError("Meta returned empty content");
71|        }
72|      }
73|      throw lastError instanceof Error ? lastError : new Error(String(lastError));
74|    },
75|  };
