1|// Shared HTTP retry and concurrency pool. One copy serves segment and
2|// classify so the retry policy stays identical and testable.
3|export interface RetryOpts {
4|  attempts?: number;
5|  backoffMs?: number;
6|}
7|
8|export function isRetryable(status: number | null, _error: string): boolean {
9|  if (status === null) return true; // network failure, no response
10|  return status === 429 || status >= 500;
11|}
12|
13|export function retryableError(message: string): Error {
14|  return Object.assign(new Error(message), { retryable: true });
15|}
16|
17|function sleep(ms: number): Promise<void> {
18|  return new Promise((resolve) => setTimeout(resolve, ms));
19|}
20|
21|export async function fetchWithRetry(
22|  fetchFn: typeof fetch,
23|  url: string,
24|  init: RequestInit,
25|  opts?: RetryOpts,
26|): Promise<Response> {
27|  const attempts = opts?.attempts ?? 3;
28|  const backoffMs = opts?.backoffMs ?? 1000;
29|  let lastError: unknown = null;
30|  for (let attempt = 1; attempt <= attempts; attempt++) {
31|    let response: Response | null = null;
32|    try {
33|      response = await fetchFn(url, init);
34|    } catch (error) {
35|      lastError = error;
36|      if (attempt < attempts) await sleep(backoffMs * attempt);
37|      continue;
38|    }
39|    if (response.ok) return response;
40|    const body = await response.text().catch(() => "");
41|    const message = `${url} failed with status ${response.status}: ${body.slice(0, 300)}`;
42|    if (!isRetryable(response.status, message) || attempt === attempts) {
43|      throw Object.assign(new Error(message), { status: response.status, retryable: false });
44|    }
45|    lastError = message;
46|    await sleep(backoffMs * attempt);
47|  }
48|  throw lastError instanceof Error ? lastError : new Error(String(lastError));
49|}
50|
51|// Bounded parallelism that keeps input order in the output.
52|export async function runPool<T, R>(items: T[], limit: number, fn: (item: T, index: number) => Promise<R>): Promise<R[]> {
53|  const results = new Array<R>(items.length);
54|  let next = 0;
55|  const workers = new Array(Math.min(limit, items.length)).fill(null).map(async () => {
56|    while (next < items.length) {
57|      const index = next;
58|      next += 1;
59|      results[index] = await fn(items[index] as T, index);
60|    }
61|  });
62|  await Promise.all(workers);
63|  return results;
64|}

